QAtomicInteger<int> g_liveSources { 0 };
QAtomicInteger<int> g_liveContentObjects { 0 };

constexpr int kMaxBars = 64;                 // spectrum.frag u_bars[64]; spectrum_frame_inputs.MAX_LEVELS
constexpr double kShaderInputScale = 0.55;   // spectrum_solid_hysteresis.SPECTRUM_SHADER_INPUT_SCALE
constexpr double kBaseHeight = 80.0;         // spectrum_solid_hysteresis._SPECTRUM_BASE_HEIGHT
constexpr double kExpandedGain = 1.2;        // spectrum_display_bar_count.SPECTRUM_EXPANDED_HORIZONTAL_BAR_GAIN
constexpr double kMaxBarGap = 4.0;           // implementations/spectrum.py MAX_BAR_GAP
constexpr float kFullTriangle[6] = { -1.0f, -1.0f, 3.0f, -1.0f, -1.0f, 3.0f };

QShader shaderFrom(const unsigned char *data, unsigned int size)
{
    return QShader::fromSerialized(QByteArray(reinterpret_cast<const char *>(data), int(size)));
}

// ---- Python's arithmetic, exactly (CPython's float remainder and floor division) -----------------------------------

double pyMod(double a, double b)
{
    double mod = std::fmod(a, b);
    if (mod != 0.0) {
        if ((b < 0.0) != (mod < 0.0))
            mod += b;
    } else {
        mod = std::copysign(0.0, b);
    }
    return mod;
}

double pyFloorDiv(double a, double b)
{
    double mod = std::fmod(a, b);
    double div = (a - mod) / b;
    if (mod != 0.0) {
        if ((b < 0.0) != (mod < 0.0))
            div -= 1.0;
    }
    double floordiv;
    if (div != 0.0) {
        floordiv = std::floor(div);
        if (div - floordiv > 0.5)
            floordiv += 1.0;
    } else {
        floordiv = std::copysign(0.0, a / b);
    }
    return floordiv;
}

// Python's min(a, b) and max(a, b): the first argument unless the second is strictly smaller (larger).
double pyMin(double a, double b) { return b < a ? b : a; }
double pyMax(double a, double b) { return b > a ? b : a; }
double unit(double x) { return pyMax(0.0, pyMin(1.0, x)); }

// implementation_values.safe_hue
double safeHue(double value)
{
    const double raw = pyMod(value, 1.0);
    return raw < 0.001 ? pyMod(raw + 0.002, 1.0) : raw;
}

// spectrum_solid_hysteresis.compute_spectrum_height_scale
double heightScale(double renderHeight)
{
    const double raw = pyMax(1.0, renderHeight / kBaseHeight);
    const double scale = 1.0 + (std::sqrt(raw) - 1.0) * 1.0;
    return pyMin(1.85, scale);
}

// spectrum_display_bar_count.resolve_display_bar_count for Spectrum on the expanded card
int displayBarCount(int authoredBarCount, int quarters)
{
    const int authored = authoredBarCount > 1 ? authoredBarCount : 1;
    if (quarters % 2)
        return authored;
    const int gained = int(double(authored) * kExpandedGain + 0.5);
    const int capped = gained < kMaxBars ? gained : kMaxBars;
    return authored > capped ? authored : capped;
}

// spectrum_display_bar_count.resample_levels: `source` has `n` values; `count` out.
void resampleLevels(const double *source, int n, int count, double *out)
{
    if (count == n || n == 0) {
        for (int i = 0; i < count; ++i)
            out[i] = i < n ? source[i] : 0.0;
        return;
    }
    if (count == 1 || n == 1) {
        for (int i = 0; i < count; ++i)
            out[i] = source[0];
        return;
    }
    const double step = double(n - 1) / double(count - 1);
    for (int index = 0; index < count; ++index) {
        const double position = double(index) * step;
        int low = int(position);
        if (low > n - 2)
            low = n - 2;
        const double t = position - double(low);
        out[index] = source[low] + (source[low + 1] - source[low]) * t;
    }
}

// ---- the record (spectrum_native_schema version 1, through the generated table) ------------------------------------

const fa::Schema *spectrumSchema()
{
    for (const fa::Schema &schema : fa::kSchemas) {
        if (std::strcmp(schema.modeId, "spectrum") == 0 && schema.version == 1)
            return &schema;
    }
    return nullptr;
}

const fa::Field *recordField(const fa::Schema &schema, const char *name)
{
    for (quint32 i = 0; i < schema.fieldCount; ++i) {
        if (std::strcmp(schema.fields[i].name, name) == 0)
            return &schema.fields[i];
    }
    return nullptr;
}

class Record
{
public:
    Record(const fa::Schema &schema, const QByteArray &bytes) : m_schema(schema), m_data(bytes.constData()) {}

    bool has(const char *name) const { return recordField(m_schema, name) != nullptr; }
    double f64(const char *name, int index = 0) const
    {
        const fa::Field *field = recordField(m_schema, name);
        double value = 0.0;
        if (field)
            std::memcpy(&value, m_data + field->offset + quint32(index) * 8u, sizeof value);
        return value;
    }
    quint32 u32(const char *name) const
    {
        const fa::Field *field = recordField(m_schema, name);
        quint32 value = 0;
        if (field)
            std::memcpy(&value, m_data + field->offset, sizeof value);
        return value;
    }
    bool flag(const char *name) const { return u32(name) != 0; }
    // How many elements the field holds (0: no such field).
    int capacity(const char *name) const
    {
        const fa::Field *field = recordField(m_schema, name);
        return field ? int(field->count) : 0;
    }
    // implementation_values.rgba: each raw channel over 255, clamped to [0, 1] (alpha 255 stored when absent).
    void rgba(const char *name, double out[4]) const
    {
        for (int i = 0; i < 4; ++i)
            out[i] = pyMax(0.0, pyMin(1.0, f64(name, i) / 255.0));
    }

private:
    const fa::Schema &m_schema;
    const char *m_data;
};

// ---- the per-frame members, set by name on the program's block (program_blocks.h) ---------------------------------

bool setFrame(BlockValues &block, const char *name, const double *values, int count, QString *error)
{
    return block.set(QByteArray(name), values, count, error);
}

bool setFrame(BlockValues &block, const char *name, double value, QString *error)
{
    return block.set(QByteArray(name), &value, 1, error);
}

bool readNumbers(const QJsonObject &o, const char *key, double *out, int count, QString *error)
{
    const QJsonValue value = o.value(QLatin1String(key));
    if (count == 1) {
        if (!value.isDouble() || !std::isfinite(value.toDouble())) {
            *error = QStringLiteral("'%1' is a finite number").arg(QLatin1String(key));
            return false;
        }
        *out = value.toDouble();
        return true;
    }
    const QJsonArray array = value.toArray();
    if (array.size() != count) {
        *error = QStringLiteral("'%1' is %2 finite numbers").arg(QLatin1String(key)).arg(count);
        return false;
    }
    for (int i = 0; i < count; ++i) {
        if (!array.at(i).isDouble() || !std::isfinite(array.at(i).toDouble())) {
            *error = QStringLiteral("'%1' is %2 finite numbers").arg(QLatin1String(key)).arg(count);
            return false;
        }
        out[i] = array.at(i).toDouble();
    }
    return true;
}

QJsonArray numbers(const double *values, int count)
{
    QJsonArray array;
    for (int i = 0; i < count; ++i)
        array.append(values[i]);
    return array;
}

