// ------------------------------------------------------------------------------------------------- the presentation

bool SpectrumPresentation::fromJson(const QByteArray &json, SpectrumPresentation *out, QString *error)
{
    QJsonParseError parse;
    const QJsonDocument document = QJsonDocument::fromJson(json, &parse);
    if (parse.error != QJsonParseError::NoError || !document.isObject()) {
        *error = QStringLiteral("the Spectrum presentation is a JSON object");
        return false;
    }
    const QJsonObject o = document.object();
    SpectrumPresentation p;
    const QJsonValue quarters = o.value(QStringLiteral("quarters"));
    if (!quarters.isDouble() || quarters.toInt(-1) < 0 || quarters.toInt(-1) > 3) {
        *error = QStringLiteral("'quarters' is 0, 1, 2 or 3");
        return false;
    }
    p.quarters = quarters.toInt();
    double fade = 0.0;
    if (!readNumbers(o, "item_size", p.itemSize, 2, error) || !readNumbers(o, "oriented_size", p.orientedSize, 2, error)
        || !readNumbers(o, "content_rect", p.contentRect, 4, error)
        || !readNumbers(o, "viewport_extent", p.viewportExtent, 2, error)
        || !readNumbers(o, "visual_scale", &p.visualScale, 1, error) || !readNumbers(o, "dpr", &p.dpr, 1, error)
        || !readNumbers(o, "content_fade", &fade, 1, error)
        || !readNumbers(o, "window_from_target", p.windowFromTarget, 6, error)
        || !readNumbers(o, "item_from_window", p.itemFromWindow, 6, error)
        || !readNumbers(o, "target_size", p.targetSize, 2, error))
        return false;
    p.contentFade = fade;
    const QJsonValue expanded = o.value(QStringLiteral("expanded"));
    if (!expanded.isBool()) {
        *error = QStringLiteral("'expanded' is a boolean");
        return false;
    }
    p.expanded = expanded.toBool();
    p.valid = true;
    *out = p;
    return true;
}

QJsonObject SpectrumPresentation::toJson() const
{
    QJsonObject o;
    o.insert(QStringLiteral("valid"), valid);
    o.insert(QStringLiteral("quarters"), quarters);
    o.insert(QStringLiteral("item_size"), numbers(itemSize, 2));
    o.insert(QStringLiteral("oriented_size"), numbers(orientedSize, 2));
    o.insert(QStringLiteral("content_rect"), numbers(contentRect, 4));
    o.insert(QStringLiteral("viewport_extent"), numbers(viewportExtent, 2));
    o.insert(QStringLiteral("visual_scale"), visualScale);
    o.insert(QStringLiteral("dpr"), dpr);
    o.insert(QStringLiteral("content_fade"), contentFade);
    o.insert(QStringLiteral("expanded"), expanded);
    o.insert(QStringLiteral("window_from_target"), numbers(windowFromTarget, 6));
    o.insert(QStringLiteral("item_from_window"), numbers(itemFromWindow, 6));
    o.insert(QStringLiteral("target_size"), numbers(targetSize, 2));
    return o;
}

bool SpectrumPresentation::operator==(const SpectrumPresentation &o) const
{
    return valid == o.valid && quarters == o.quarters && expanded == o.expanded && visualScale == o.visualScale
        && dpr == o.dpr && contentFade == o.contentFade && std::memcmp(itemSize, o.itemSize, sizeof itemSize) == 0
        && std::memcmp(orientedSize, o.orientedSize, sizeof orientedSize) == 0
        && std::memcmp(contentRect, o.contentRect, sizeof contentRect) == 0
        && std::memcmp(viewportExtent, o.viewportExtent, sizeof viewportExtent) == 0
        && std::memcmp(windowFromTarget, o.windowFromTarget, sizeof windowFromTarget) == 0
        && std::memcmp(itemFromWindow, o.itemFromWindow, sizeof itemFromWindow) == 0
        && std::memcmp(targetSize, o.targetSize, sizeof targetSize) == 0;
}

// ------------------------------------------------------------------------------------------------- the block layout

const char *const kSpectrumFrameMembers[] = {
    "u_bars", "u_peaks", "u_bar_count", "u_bars_left", "u_bar_width_px", "u_bar_gap_px", "u_bar_span_px",
    "u_rainbow_hue_offset", "u_ghost_hue_offset", "u_time", "u_playing", nullptr };

bool SpectrumProgram::fromPack(const QByteArray &qsb, SpectrumProgram *out, QString *error)
{
    static QAtomicInteger<quint64> generations { 0 };
    SpectrumProgram program;
    program.compiledIn = qsb.isEmpty();
    program.fragment = program.compiledIn ? shaderFrom(spectrum_frag_qsb, spectrum_frag_qsb_size)
                                          : QShader::fromSerialized(qsb);
    if (!program.fragment.isValid()) {
        *error = QStringLiteral("the Spectrum fragment pack does not load (a .qsb from tools/regen_qrc.py --shaders)");
        return false;
    }
    program.layout = BlockLayout::reflect(program.fragment, QByteArrayLiteral("SpectrumDraw"));
    if (!program.layout.valid() || program.layout.binding() < 0) {
        *error = QStringLiteral("the Spectrum fragment pack holds no SpectrumDraw block");
        return false;
    }
    program.shaderGeneration = generations.fetchAndAddRelaxed(1) + 1;
    *out = program;
    return true;
}

bool SpectrumProgram::setSettings(const QJsonObject &values, QString *error)
{
    if (!layout.valid()) {
        *error = QStringLiteral("the Spectrum settings come after its fragment pack");
        return false;
    }
    BlockValues check(layout);
    if (!check.setJson(values, error))
        return false;
    for (const char *const *name = kSpectrumFrameMembers; *name; ++name) {
        if (values.contains(QLatin1String(*name))) {
            *error = QStringLiteral("'%1' is computed per frame by the core, not a setting").arg(QLatin1String(*name));
            return false;
        }
    }
    settings = values;
    return true;
}

// ------------------------------------------------------------------------------------------------- the block

bool spectrumBlock(const QByteArray &bytes, const SpectrumPresentation &p, const SpectrumProgram &program,
                   QByteArray *block, QJsonObject *facts, QString *reason)
{
    const fa::Schema *schema = spectrumSchema();
    if (!program.layout.valid() || !schema) {
        *reason = QStringLiteral("no Spectrum program (its fragment pack) or no schema");
        return false;
    }
    if (!p.valid) {
        *reason = QStringLiteral("no presentation");
        return false;
    }
    if (quint32(bytes.size()) != schema->recordBytes) {
        *reason = QStringLiteral("a %1-byte record is not Spectrum's %2").arg(bytes.size()).arg(schema->recordBytes);
        return false;
    }
    const Record record(*schema, bytes);

    // QuickSpectrumRenderer.render, line for line.
    const quint32 storedCount = record.u32("bar_count");
    int count = storedCount < quint32(kMaxBars) ? int(storedCount) : kMaxBars;
    if (count <= 0) {
        *reason = QStringLiteral("no bars");
        return false;
    }
    double logicalBars[kMaxBars] = {};
    double logicalPeaks[kMaxBars] = {};
    // Kept lengths clamped to the stack arrays and the fields (audit 14 Nov, L1): the reader refuses a length over 64,
    // but spectrum_block takes any bytes and the skip_head_check control admits any record.
    const auto keptLength = [&record](const char *lengthName, const char *fieldName) {
        const quint32 stored = record.u32(lengthName);
        const quint32 limit = quint32(qMin(kMaxBars, record.capacity(fieldName)));
        return int(stored < limit ? stored : limit);
    };
    int barsLength = keptLength("bars_len", "bars");
    int peaksLength = keptLength("peaks_len", "peaks");
    for (int i = 0; i < barsLength; ++i)
        logicalBars[i] = record.f64("bars", i);
    for (int i = 0; i < peaksLength; ++i)
        logicalPeaks[i] = record.f64("peaks", i);
    if (p.expanded) {
        const int drawn = displayBarCount(count, p.quarters);
        if (drawn != count) {
            double levels[kMaxBars] = {};
            double peakLevels[kMaxBars] = {};
            for (int i = 0; i < count; ++i)
                levels[i] = i < barsLength ? logicalBars[i] : 0.0;
            const int keptPeaks = peaksLength < count ? peaksLength : count;
            for (int i = 0; i < count; ++i)
                peakLevels[i] = i < keptPeaks ? logicalPeaks[i] : levels[i];
            resampleLevels(levels, count, drawn, logicalBars);
            resampleLevels(peakLevels, count, drawn, logicalPeaks);
            barsLength = peaksLength = drawn;
            count = drawn;
        }
    }
    // prepare_spectrum_shader_levels
    struct { double bars[kMaxBars] = {}; double peaks[kMaxBars] = {}; } values;
    for (int i = 0; i < count; ++i) {
        const double bar = i < barsLength ? logicalBars[i] : 0.0;
        values.bars[i] = bar;
        values.peaks[i] = i < peaksLength ? logicalPeaks[i] : bar;
    }
    for (int i = 0; i < count; ++i) {
        values.bars[i] *= kShaderInputScale;
        values.peaks[i] *= kShaderInputScale;
    }

    // compute_quick_spectrum_layout
    const double contentX = p.contentRect[0];
    const double contentY = p.contentRect[1];
    const double contentWidth = p.contentRect[2];
    const double contentHeight = p.contentRect[3];
    const double extentHeight = p.viewportExtent[1];
    const double scale = p.visualScale;
    if (pyMin(pyMin(contentWidth, contentHeight), pyMin(extentHeight, scale)) <= 0.0) {
        *reason = QStringLiteral("Spectrum layout geometry must be positive");
        return false;
    }
    const double margin = 8.0 * scale;
    const double leftInset = 1.0 * scale;
    const double rightInset = 3.0 * scale;
    const double gap = pyMax(0.0, pyMin(kMaxBarGap, record.f64("bar_gap"))) * scale;
    const double barRegionWidth = contentWidth - (2.0 * margin) - leftInset - rightInset;
    const double totalGap = gap * double(count - 1 > 0 ? count - 1 : 0);
    const double usableWidth = barRegionWidth - totalGap;
    if (usableWidth <= 0.0) {
        *reason = QStringLiteral("Spectrum viewport is too narrow for its bars");
        return false;
    }
    const double barWidth = usableWidth / double(count);
    const double span = (barWidth * double(count)) + totalGap;
    const double innerHeight = pyMax(0.0, extentHeight - 12.0);
    const int segmentsRaw = int(pyFloorDiv(innerHeight, 5.0));
    const int segments = segmentsRaw < 8 ? 8 : (segmentsRaw > 64 ? 64 : segmentsRaw);
    const double barsLeft = contentX + margin + leftInset;
    const double barHeightScale = heightScale(extentHeight);

    const bool rainbowEnabled = record.flag("rainbow_enabled");
    const bool rainbowPerBar = record.flag("rainbow_per_bar");
    const double rainbowSpeed = pyMax(0.01, pyMin(5.0, record.f64("rainbow_speed")));
    const double animationTime = record.f64("animation_time");
    double hue = 0.0;
    if (rainbowEnabled)
        hue = safeHue(animationTime * rainbowSpeed * 0.1);
    else if (rainbowPerBar)
        hue = safeHue(animationTime * 0.05);

    // Every Settings- and card-derived member is the program's (resolved in Python, packed by name); the core fills
    // only what follows the frame.
    BlockValues packed(program.layout);
    if (!packed.setJson(program.settings, reason))
        return false;
    QString refused;
    const double barCount = double(count);
    const double playing = record.flag("playing") ? 1.0 : 0.0;
    const double ghostHue = safeHue(animationTime * rainbowSpeed * 0.1);
    const double clock = pyMod(animationTime, 3600.0);
    if (!setFrame(packed, "u_bars", values.bars, count, &refused)
        || !setFrame(packed, "u_peaks", values.peaks, count, &refused)
        || !setFrame(packed, "u_bar_count", barCount, &refused)
        || !setFrame(packed, "u_bars_left", barsLeft, &refused)
        || !setFrame(packed, "u_bar_width_px", barWidth, &refused)
        || !setFrame(packed, "u_bar_gap_px", gap, &refused)
        || !setFrame(packed, "u_bar_span_px", span, &refused)
        || !setFrame(packed, "u_rainbow_hue_offset", hue, &refused)
        || !setFrame(packed, "u_ghost_hue_offset", ghostHue, &refused)
        || !setFrame(packed, "u_time", clock, &refused)
        || !setFrame(packed, "u_playing", playing, &refused)) {
        *reason = QStringLiteral("the pack's block refuses a frame member: %1").arg(refused);
        return false;
    }
    *block = packed.bytes();
    if (facts) {
        facts->insert(QStringLiteral("bar_count"), count);
        facts->insert(QStringLiteral("segments"), segments);
        facts->insert(QStringLiteral("bars_left"), barsLeft);
        facts->insert(QStringLiteral("bar_width"), barWidth);
        facts->insert(QStringLiteral("bar_gap"), gap);
        facts->insert(QStringLiteral("bar_span"), span);
        facts->insert(QStringLiteral("height_scale"), barHeightScale);
        facts->insert(QStringLiteral("hue"), hue);
        facts->insert(QStringLiteral("block_bytes"), block->size());
        facts->insert(QStringLiteral("unfilled"), QJsonArray::fromStringList(packed.unfilled()));
        facts->insert(QStringLiteral("compiled_in"), program.compiledIn);
    }
    reason->clear();
    return true;
}

// ------------------------------------------------------------------------------------------------- the source

SpectrumSource::SpectrumSource()
{
    g_liveSources.fetchAndAddRelaxed(1);
}

SpectrumSource::~SpectrumSource()
{
    // The last owner: the node on the render thread, or the item when no node ever read (no read can be in progress).
    releaseRetired();
    for (PacketReader *reader : m_retiring) { // the last owner: nothing can wait on the source any more
        reader->release();
        delete reader;
    }
    m_retiring.clear();
    if (m_current) {
        m_current->retire();
        m_current->release();
        delete m_current;
        m_current = nullptr;
    }
    g_liveSources.fetchAndAddRelaxed(-1);
}

int SpectrumSource::liveSources()
{
    return g_liveSources.loadRelaxed();
}

bool SpectrumSource::bind(const QString &mappingName, const PacketReaderConfig &config, QString *error)
{
    PacketReader *reader = PacketReader::open(mappingName, config, error);
    if (!reader)
        return false;
    QMutexLocker lock(&m_mutex);
    if (m_current) {
        m_current->retire(); // D1: Retiring at once; the render thread releases it at its next sync
        m_retiring.append(m_current);
        ++m_retired;
    }
    m_current = reader;
    m_mapping = mappingName;
    ++m_binds;
    return true;
}

void SpectrumSource::unbind()
{
    QMutexLocker lock(&m_mutex);
    if (!m_current)
        return;
    m_current->retire();
    m_retiring.append(m_current);
    m_current = nullptr;
    m_mapping.clear();
    ++m_retired;
}

void SpectrumSource::retireCurrent()
{
    QMutexLocker lock(&m_mutex);
    if (m_current)
        m_current->retire();
}

void SpectrumSource::setPresentation(const SpectrumPresentation &presentation)
{
    QMutexLocker lock(&m_mutex);
    m_presentation = presentation;
    ++m_presentationGeneration;
}

void SpectrumSource::setProgram(const SpectrumProgram &program)
{
    QMutexLocker lock(&m_mutex);
    m_program = program;
    ++m_presentationGeneration;
}

bool SpectrumSource::setSettings(const QJsonObject &settings, QString *error)
{
    QMutexLocker lock(&m_mutex);
    SpectrumProgram program = m_program;
    if (!program.setSettings(settings, error))
        return false;
    if (program.settings == m_program.settings)
        return true;                          // unchanged: nothing is recorded
    m_program = program;
    ++m_presentationGeneration;
    return true;
}

void SpectrumSource::dropRetainedFrame()
{
    QMutexLocker lock(&m_mutex);
    if (m_current)
        m_current->dropRetainedFrame();
}

bool SpectrumSource::readHead(SlotHead *out)
{
    QMutexLocker lock(&m_mutex); // the current reader is never released while it is current
    return m_current && m_current->readHead(out);
}

bool SpectrumSource::waitPaused(int timeoutMs)
{
    // The harness's pause_in_copy hook. The reader is waited on without the lock; while any wait is in progress the
    // retire job keeps every retired reader alive (audit 14 Nov, L9: an unbind then a sync deleted it under the wait).
    PacketReader *reader = nullptr;
    {
        QMutexLocker lock(&m_mutex);
        reader = m_current;
        if (!reader)
            return false;
        ++m_waiters;
    }
    const bool paused = reader->waitPaused(timeoutMs);
    QMutexLocker lock(&m_mutex);
    --m_waiters;
    return paused;
}

void SpectrumSource::resume()
{
    QMutexLocker lock(&m_mutex);
    if (m_current)
        m_current->resume();
    for (PacketReader *reader : m_retiring)
        reader->resume();
}

void SpectrumSource::releaseRetired()
{
    QList<PacketReader *> retiring;
    {
        QMutexLocker lock(&m_mutex);
        if (m_waiters > 0)
            return; // a harness wait holds a reader: released at the first sync after it returns
        retiring.swap(m_retiring);
    }
    for (PacketReader *reader : retiring) {
        reader->release(); // the consumer's thread: its retained frame and its pin go; the last pin unmaps
        const QJsonObject state = reader->stateJson();
        delete reader;
        QMutexLocker lock(&m_mutex);
        ++m_released;
        m_lastReader = state;
    }
}

bool SpectrumSource::sync()
{
    m_syncProbe.hit(); // D5.4: the read's thread, and whether it held a Python thread state
    releaseRetired(); // the render-thread retire job
    PacketReader *current = nullptr;
    bool presentationTaken = false;
    SpectrumPresentation presentation;
    SpectrumProgram program;
    {
        QMutexLocker lock(&m_mutex);
        current = m_current;
        if (m_presentationGeneration != m_takenGeneration) {
            m_takenGeneration = m_presentationGeneration;
            presentation = m_presentation;
            program = m_program;
            presentationTaken = true;
        }
    }
    bool accepted = false;
    bool rejected = false;
    bool changed = false;
    if (presentationTaken && presentation != m_drawn) {
        m_drawn = presentation;
        changed = true;
    }
    if (presentationTaken && (program.shaderGeneration != m_drawnProgram.shaderGeneration
                              || program.settings != m_drawnProgram.settings)) {
        m_drawnProgram = program; // a new pack or new settings: recorded once, nothing per frame at rest
        changed = true;
    }
    QString result = QStringLiteral("unbound");
    if (current) {
        const ReadResult read = current->read(); // the accept edge (D2), on the render thread
        result = QString::fromLatin1(readResultName(read));
        SlotHead head;
        const QByteArray *retained = nullptr;
        const bool holds = current->retained(&head, &retained);
        // render_contract.snapshot_is_render_admissible for Spectrum, a mode whose first visible reactive output must
        // come from its tracked source (mode_capabilities.requires_authoritative_first_source): a frame that is not a
        // present frame, or a playing one whose reactive source is not its own activation's, is not drawn and the last
        // admitted frame stays (the Python node's rule). The bits are the slot head's (packet_abi FLAG_*).
        const bool admissible = holds && (head.flags & fa::kFlagPresentFrame)
            && (!(head.flags & fa::kFlagPlaying) || (head.flags & fa::kFlagSourceCurrent));
        if (read == ReadResult::Accepted && holds && !admissible) {
            rejected = true;
        } else if (read == ReadResult::Accepted && holds) {
            if (m_record.size() != retained->size())
                m_record.resize(retained->size());
            std::memcpy(m_record.data(), retained->constData(), size_t(retained->size()));
            m_hasFrame = true;
            accepted = true;
            changed = true;
        } else if (m_hasFrame && !holds) {
            m_hasFrame = false; // dropped (R-184's edge), or another stream bound: nothing of the old one is drawn
            changed = true;
        }
    } else if (m_hasFrame) {
        m_hasFrame = false;
        changed = true;
    }
    QMutexLocker lock(&m_reportMutex);
    ++m_syncs;
    if (accepted)
        ++m_accepted;
    if (rejected)
        ++m_admissionRejected;
    m_lastResult = result;
    m_reportedFrame = m_hasFrame;
    return changed;
}

void SpectrumSource::noteRecorded(bool drawn, const QString &reason, const QJsonObject &facts)
{
    QMutexLocker lock(&m_reportMutex);
    ++m_records;
    if (drawn)
        ++m_draws;
    m_lastReason = reason;
    m_lastFacts = facts;
}

QJsonObject SpectrumSource::stateJson() const
{
    QJsonObject o;
    {
        QMutexLocker lock(&m_mutex);
        o.insert(QStringLiteral("mapping"), m_mapping);
        o.insert(QStringLiteral("binds"), double(m_binds));
        o.insert(QStringLiteral("retired"), double(m_retired));
        o.insert(QStringLiteral("released"), double(m_released));
        o.insert(QStringLiteral("retiring"), int(m_retiring.size()));
        o.insert(QStringLiteral("presentation"), m_presentation.toJson());
        QJsonObject program;
        program.insert(QStringLiteral("loaded"), m_program.layout.valid());
        program.insert(QStringLiteral("compiled_in"), m_program.compiledIn);
        program.insert(QStringLiteral("shader_generation"), double(m_program.shaderGeneration));
        program.insert(QStringLiteral("settings"), m_program.settings);
        program.insert(QStringLiteral("block"), m_program.layout.toJson());
        o.insert(QStringLiteral("program"), program);
        o.insert(QStringLiteral("reader"), m_current ? QJsonValue(m_current->stateJson()) : QJsonValue());
        o.insert(QStringLiteral("last_released_reader"), m_lastReader.isEmpty() ? QJsonValue() : QJsonValue(m_lastReader));
    }
    QMutexLocker lock(&m_reportMutex);
    o.insert(QStringLiteral("syncs"), double(m_syncs));
    o.insert(QStringLiteral("accepted"), double(m_accepted));
    o.insert(QStringLiteral("admission_rejected"), double(m_admissionRejected));
    o.insert(QStringLiteral("syncs_probed"), double(m_syncProbe.calls.loadRelaxed()));
    o.insert(QStringLiteral("syncs_on_gui_thread"), double(m_syncProbe.callsOnGuiThread.loadRelaxed()));
    o.insert(QStringLiteral("syncs_with_python_thread_state"),
             double(m_syncProbe.callsWithPythonThreadState.loadRelaxed()));
    o.insert(QStringLiteral("has_frame"), m_reportedFrame);
    o.insert(QStringLiteral("last_read"), m_lastResult);
    o.insert(QStringLiteral("records"), double(m_records));
    o.insert(QStringLiteral("draws"), double(m_draws));
    o.insert(QStringLiteral("last_reason"), m_lastReason);
    o.insert(QStringLiteral("last_facts"), m_lastFacts);
    return o;
}

// ------------------------------------------------------------------------------------------------- the content

struct SpectrumContent::Resources
{
    QRhi *rhi = nullptr;
    QRhiRenderPassDescriptor *pass = nullptr; // the surface target's (not owned)
    std::unique_ptr<QRhiBuffer> vertices;
    std::unique_ptr<QRhiBuffer> uniforms;
    std::unique_ptr<QRhiBuffer> conventions;
    std::unique_ptr<QRhiShaderResourceBindings> clearBindings;
    std::unique_ptr<QRhiShaderResourceBindings> bindings;
    std::unique_ptr<QRhiGraphicsPipeline> clearPipeline;
    std::unique_ptr<QRhiGraphicsPipeline> pipeline;
    bool staticUploaded = false;
    int objects = 0;
    quint64 shaderGeneration = 0; // the program pack the pipeline was built from
};

SpectrumContent::SpectrumContent(std::shared_ptr<SpectrumSource> source) : m_source(std::move(source)) {}

SpectrumContent::~SpectrumContent()
{
    release();
}

int SpectrumContent::liveResources() const
{
    return m_res ? m_res->objects : 0;
}

void SpectrumContent::release()
{
    if (!m_res)
        return;
    g_liveContentObjects.fetchAndAddRelaxed(-m_res->objects);
    m_res->pipeline.reset();
    m_res->clearPipeline.reset();
    m_res->bindings.reset();
    m_res->clearBindings.reset();
    m_res->conventions.reset();
    m_res->uniforms.reset();
    m_res->vertices.reset();
    m_res.reset();
}

bool SpectrumContent::ensure(QRhi *rhi, ColorTarget &target, QString *error)
{
    const SpectrumProgram &program = m_source->drawnProgram();
    if (m_res && (m_res->rhi != rhi || m_res->pass != target.renderPass.get()
                  || m_res->shaderGeneration != program.shaderGeneration))
        release();                            // a new pack: its pipeline and block buffer are rebuilt
    if (m_res)
        return true;
    if (m_failed && m_failedRhi == rhi && m_failedPass == target.renderPass.get()
        && m_failedGeneration == program.shaderGeneration) {
        *error = m_failedError;               // failed closed: nothing is created again for the same inputs (M2)
        return false;
    }
    if (build(rhi, target, error)) {
        m_failed = false;
        return true;
    }
    // The failure edge: recorded once, reported through the source's state.
    m_failed = true;
    m_failedRhi = rhi;
    m_failedPass = target.renderPass.get();
    m_failedGeneration = program.shaderGeneration;
    m_failedError = *error;
    ++m_failures;
    QJsonObject facts;
    facts.insert(QStringLiteral("content_failed"), true);
    facts.insert(QStringLiteral("content_failures"), double(m_failures));
    m_source->noteRecorded(false, QStringLiteral("the content failed: %1").arg(*error), facts);
    return false;
}

bool SpectrumContent::build(QRhi *rhi, ColorTarget &target, QString *error)
{
    const SpectrumProgram &program = m_source->drawnProgram();
    const BlockLayout &layout = program.layout;
    const QShader vs = shaderFrom(spectrum_vert_qsb, spectrum_vert_qsb_size);
    const QShader &fs = program.fragment;
    const QShader clear = shaderFrom(clear_frag_qsb, clear_frag_qsb_size);
    if (!vs.isValid() || !fs.isValid() || !clear.isValid() || !layout.valid()) {
        *error = QStringLiteral("Spectrum has no program (its fragment pack) or its block is not valid");
        return false;
    }
    auto res = std::make_unique<Resources>();
    res->rhi = rhi;
    res->pass = target.renderPass.get();
    res->shaderGeneration = program.shaderGeneration;
    res->vertices.reset(rhi->newBuffer(QRhiBuffer::Immutable, QRhiBuffer::VertexBuffer, sizeof(kFullTriangle)));
    res->uniforms.reset(rhi->newBuffer(QRhiBuffer::Dynamic, QRhiBuffer::UniformBuffer, quint32(layout.size())));
    res->conventions.reset(rhi->newBuffer(QRhiBuffer::Dynamic, QRhiBuffer::UniformBuffer, sizeof(ConventionsBlock)));
    res->vertices->setName(QByteArrayLiteral("srpss core spectrum vertices"));
    res->uniforms->setName(QByteArrayLiteral("srpss core spectrum block"));
    res->conventions->setName(QByteArrayLiteral("srpss core spectrum conventions block"));
    if (!res->vertices->create() || !res->uniforms->create() || !res->conventions->create()) {
        *error = QStringLiteral("Spectrum's buffers could not be created");
        return false;
    }
    res->clearBindings.reset(rhi->newShaderResourceBindings());
    res->clearBindings->setName(QByteArrayLiteral("srpss core spectrum clear bindings"));
    res->bindings.reset(rhi->newShaderResourceBindings());
    res->bindings->setName(QByteArrayLiteral("srpss core spectrum bindings"));
    res->bindings->setBindings({
        QRhiShaderResourceBinding::uniformBuffer(layout.binding(), QRhiShaderResourceBinding::FragmentStage,
                                                 res->uniforms.get()),
        QRhiShaderResourceBinding::uniformBuffer(kConventionsBinding, QRhiShaderResourceBinding::FragmentStage,
                                                 res->conventions.get()) });
    if (!res->clearBindings->create() || !res->bindings->create()) {
        *error = QStringLiteral("Spectrum's bindings could not be created");
        return false;
    }
    QRhiVertexInputLayout input;
    input.setBindings({ { quint32(2 * sizeof(float)) } });
    input.setAttributes({ { 0, 0, QRhiVertexInputAttribute::Float2, 0 } });

    // The clear: every texel transparent, blending off (targets.h rule B: cleared by a draw).
    res->clearPipeline.reset(rhi->newGraphicsPipeline());
    res->clearPipeline->setName(QByteArrayLiteral("srpss core spectrum clear"));
    res->clearPipeline->setTargetBlends({ QRhiGraphicsPipeline::TargetBlend() });
    res->clearPipeline->setShaderStages({ { QRhiShaderStage::Vertex, vs }, { QRhiShaderStage::Fragment, clear } });
    res->clearPipeline->setVertexInputLayout(input);
    res->clearPipeline->setCullMode(QRhiGraphicsPipeline::None);
    res->clearPipeline->setShaderResourceBindings(res->clearBindings.get());
    res->clearPipeline->setRenderPassDescriptor(res->pass);
    // The bars: the Python render host's blending (straight alpha over the transparent target, so the target holds
    // premultiplied colour, which the composite draws).
    QRhiGraphicsPipeline::TargetBlend blend;
    blend.enable = true;
    blend.srcColor = QRhiGraphicsPipeline::SrcAlpha;
    blend.dstColor = QRhiGraphicsPipeline::OneMinusSrcAlpha;
    blend.opColor = QRhiGraphicsPipeline::Add;
    blend.srcAlpha = QRhiGraphicsPipeline::One;
    blend.dstAlpha = QRhiGraphicsPipeline::OneMinusSrcAlpha;
    blend.opAlpha = QRhiGraphicsPipeline::Add;
    res->pipeline.reset(rhi->newGraphicsPipeline());
    res->pipeline->setName(QByteArrayLiteral("srpss core spectrum"));
    res->pipeline->setTargetBlends({ blend });
    res->pipeline->setShaderStages({ { QRhiShaderStage::Vertex, vs }, { QRhiShaderStage::Fragment, fs } });
    res->pipeline->setVertexInputLayout(input);
    res->pipeline->setCullMode(QRhiGraphicsPipeline::None);
    res->pipeline->setShaderResourceBindings(res->bindings.get());
    res->pipeline->setRenderPassDescriptor(res->pass);
    if (!res->clearPipeline->create() || !res->pipeline->create()) {
        *error = QStringLiteral("Spectrum's pipelines could not be created");
        return false;
    }
    res->objects = 7; // three buffers, two bindings, two pipelines
    g_liveContentObjects.fetchAndAddRelaxed(res->objects);
    m_res = std::move(res);
    return true;
}

bool SpectrumContent::record(QRhi *rhi, QRhiCommandBuffer *cb, ColorTarget &target, QString *error)
{
    if (!target.isValid()) {
        *error = QStringLiteral("Spectrum's surface has no target");
        return false;
    }
    if (!ensure(rhi, target, error))
        return false;
    const SpectrumSource &source = *m_source;
    QByteArray block;
    QJsonObject facts;
    QString reason = QStringLiteral("no frame");
    const bool draw = source.hasFrame()
        && spectrumBlock(source.frameRecord(), source.drawnPresentation(), source.drawnProgram(), &block, &facts,
                         &reason);
    Resources &r = *m_res;
    QRhiResourceUpdateBatch *updates = rhi->nextResourceUpdateBatch();
    if (!r.staticUploaded) {
        updates->uploadStaticBuffer(r.vertices.get(), kFullTriangle);
        const ConventionsBlock conventions = targetConventions(rhi); // F1, F2: a target the core owns
        updates->updateDynamicBuffer(r.conventions.get(), 0, sizeof(ConventionsBlock), &conventions);
        r.staticUploaded = true;
    }
    if (draw)
        updates->updateDynamicBuffer(r.uniforms.get(), 0, quint32(block.size()), block.constData());
    const QSize size = target.texture->pixelSize();
    const QRhiViewport viewport(0, 0, float(size.width()), float(size.height()));
    const QRhiCommandBuffer::VertexInput input(r.vertices.get(), 0);
    cb->beginPass(target.renderTarget.get(), QColor(0, 0, 0, 0), { 1.0f, 0 }, updates);
    cb->setGraphicsPipeline(r.clearPipeline.get());
    cb->setViewport(viewport);
    cb->setShaderResources();
    cb->setVertexInput(0, 1, &input);
    cb->draw(3);
    if (draw) {
        cb->setGraphicsPipeline(r.pipeline.get());
        cb->setViewport(viewport);
        cb->setShaderResources();
        cb->setVertexInput(0, 1, &input);
        cb->draw(3);
    }
    cb->endPass();
    m_source->noteRecorded(draw, reason, facts);
    return true;
}

int spectrumContentObjects()
{
    return g_liveContentObjects.loadRelaxed();
}

